#!/usr/bin/env bash
# shubenOS 1.0 - self-contained ISO builder (the project files are packed at the bottom of this file).
# Copyright (c) 2026 shuben / Apelegends. All rights reserved.
set -euo pipefail
[ "$(id -u)" -eq 0 ] || { echo "Run as root."; exit 1; }
export DEBIAN_FRONTEND=noninteractive
SELF="$(readlink -f "$0")"
HERE="$(dirname "$SELF")"

apt-get update
apt-get install -y --no-install-recommends live-build debootstrap squashfs-tools xorriso \
  mtools dosfstools ca-certificates grub-common grub-pc-bin grub-efi-amd64-bin \
  grub-efi-amd64-signed shim-signed isolinux syslinux-common

rm -rf /build && mkdir -p /build
sed -n '/^__PAYLOAD__$/,$p' "$SELF" | tail -n +2 | base64 -d | tar xz -C /build
echo "Project unpacked:"; ls /build
cd /build
chmod +x auto/config config/hooks/normal/* 2>/dev/null || true
lb clean --purge >/dev/null 2>&1 || true
lb config
set +e
lb build 2>&1 | tee /build/build.log
RC=${PIPESTATUS[0]}
set -e
cp /build/build.log "$HERE/build.log" || true
ISO=$(find /build -maxdepth 1 -name '*.iso' | head -n1)
if [ "$RC" -ne 0 ] || [ -z "$ISO" ]; then
  echo "ERROR: build failed (lb exit $RC). Last 60 log lines:"; tail -n 60 /build/build.log; exit 1
fi
cp "$ISO" "$HERE/shubenOS-1.0-amd64.iso"
( cd "$HERE" && sha256sum shubenOS-1.0-amd64.iso > shubenOS-1.0-amd64.iso.sha256 )
echo "DONE: shubenOS-1.0-amd64.iso"
exit 0
